 11→// Wrap returns the Agent wrapped with the appropriate interface
 12→// implementations based on the capabilities declared in its info response.
 13→// The returned value satisfies agent.Agent and whichever optional interfaces
 14→// the external binary declared support for.
 15→//
 16→// We cannot use Go embedding because *Agent implements ALL optional interface
 17→// methods, and embedding would expose all of them regardless of capabilities.
 18→// Instead, each wrapper explicitly forwards only the interfaces it should expose.
 19→func Wrap(ea *Agent) agent.Agent {
 20→	caps := ea.info.Capabilities
 21→
 22→	base := baseAgent{ea: ea}
 23→
 24→	switch {
 25→	case caps.Hooks && caps.TranscriptAnalyzer && caps.TranscriptPreparer && caps.TokenCalculator && caps.TextGenerator && caps.HookResponseWriter && caps.SubagentAwareExtractor:
 26→		return &fullAgent{baseAgent: base}
 27→	case caps.Hooks && caps.TranscriptAnalyzer && caps.TranscriptPreparer:
 28→		return &hooksAnalyzerPreparerAgent{baseAgent: base}
 29→	case caps.Hooks && caps.TranscriptAnalyzer:
 30→		return &hooksAnalyzerAgent{baseAgent: base}
 31→	case caps.Hooks && caps.TranscriptPreparer:
 32→		return &hooksPreparerAgent{baseAgent: base}
 33→	case caps.TranscriptAnalyzer && caps.TranscriptPreparer:
 34→		return &analyzerPreparerAgent{baseAgent: base}
 35→	case caps.Hooks:
 36→		return &hooksAgent{baseAgent: base}
 37→	case caps.TranscriptAnalyzer:
 38→		return &analyzerAgent{baseAgent: base}
 39→	case caps.TranscriptPreparer:
 40→		return &preparerAgent{baseAgent: base}
 41→	default:
 42→		return &base
 43→	}
 44→}
