 14→// testBinaryDir creates a temp directory with a mock entire-agent-test binary.
 15→// The binary is a shell script implementing the protocol.
 16→func testBinaryDir(t *testing.T, script string) string {
 17→	t.Helper()
 18→
 19→	dir := t.TempDir()
 20→
 21→	name := "entire-agent-test"
 22→	if runtime.GOOS == "windows" {
 23→		name += ".bat"
 24→	}
 25→
 26→	path := filepath.Join(dir, name)
 27→	if err := os.WriteFile(path, []byte(script), 0o755); err != nil {
 28→		t.Fatalf("write mock binary: %v", err)
 29→	}
 30→
 31→	return path
 32→}
 33→
 34→// mockInfoScript returns a shell script that responds to "info" with the given JSON.
 35→func mockInfoScript(infoJSON string) string {
 36→	return `#!/bin/sh
 37→case "$1" in
 38→  info)
 39→    echo '` + infoJSON + `'
 40→    ;;
 41→  detect)
 42→    echo '{"present": true}'
 43→    ;;
 44→  get-session-dir)
 45→    echo '{"session_dir": "/tmp/sessions"}'
 46→    ;;
 47→  resolve-session-file)
 48→    echo '{"session_file": "/tmp/sessions/test.jsonl"}'
 49→    ;;
 50→  get-session-id)
 51→    echo '{"session_id": "test-session-123"}'
 52→    ;;
 53→  read-session)
 54→    echo '{"session_id":"s1","agent_name":"test","repo_path":"/repo","session_ref":"ref"}'
 55→    ;;
 56→  write-session)
 57→    exit 0
 58→    ;;
 59→  format-resume-command)
 60→    echo '{"command": "test-agent resume '$3'"}'
 61→    ;;
 62→  read-transcript)
 63→    echo 'raw transcript data'
 64→    ;;
 65→  chunk-transcript)
 66→    echo '{"chunks": ["Y2h1bms="]}'
 67→    ;;
 68→  reassemble-transcript)
 69→    cat
 70→    ;;
 71→  parse-hook)
 72→    echo 'null'
 73→    ;;
 74→  install-hooks)
 75→    echo '{"hooks_installed": 2}'
 76→    ;;
 77→  uninstall-hooks)
 78→    exit 0
 79→    ;;
 80→  are-hooks-installed)
 81→    echo '{"installed": true}'
 82→    ;;
 83→  get-transcript-position)
 84→    echo '{"position": 42}'
 85→    ;;
 86→  extract-modified-files)
 87→    echo '{"files": ["a.go", "b.go"], "current_position": 10}'
 88→    ;;
 89→  extract-prompts)
 90→    echo '{"prompts": ["hello", "world"]}'
 91→    ;;
 92→  extract-summary)
 93→    echo '{"summary": "test summary", "has_summary": true}'
 94→    ;;
 95→  *)
 96→    echo "unknown subcommand: $1" >&2
 97→    exit 1
 98→    ;;
 99→esac
100→`
101→}
