122→func TestNew_Valid(t *testing.T) {
123→	t.Parallel()
124→
125→	if _, err := exec.LookPath("sh"); err != nil {
126→		t.Skip("sh not available")
127→	}
128→
129→	binPath := testBinaryDir(t, mockInfoScript(validInfoJSON))
130→	ea, err := New(binPath)
131→	if err != nil {
132→		t.Fatalf("New: %v", err)
133→	}
134→	if ea.info.Name != "test" {
135→		t.Errorf("Name = %q, want %q", ea.info.Name, "test")
136→	}
137→	if ea.info.ProtocolVersion != 1 {
138→		t.Errorf("ProtocolVersion = %d, want 1", ea.info.ProtocolVersion)
139→	}
140→}
