 165→// runEnableInteractive runs the interactive enable flow.
 166→// agents must be provided by the caller (via detectOrSelectAgent).
 167→func runEnableInteractive(ctx context.Context, w io.Writer, agents []agent.Agent, opts EnableOptions) error {
 168→	// Uninstall hooks for agents that were previously active but are no longer selected
 169→	if err := uninstallDeselectedAgentHooks(ctx, w, agents); err != nil {
 170→		return fmt.Errorf("failed to clean up deselected agents: %w", err)
 171→	}
 172→
 173→	// Setup agent hooks for all selected agents
 174→	for _, ag := range agents {
 175→		if _, err := setupAgentHooks(ctx, ag, opts.LocalDev, opts.ForceHooks); err != nil {
 176→			return fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err)
 177→		}
 178→	}
 179→
 180→	// Setup .entire directory
 181→	if _, err := setupEntireDirectory(ctx); err != nil {
 182→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 183→	}
 184→
 185→	// Load existing settings to preserve other options (like strategy_options.push)
 186→	settings, err := LoadEntireSettings(ctx)
 187→	if err != nil {
 188→		// If we can't load, start with defaults
 189→		settings = &EntireSettings{}
 190→	}
 191→	// Update the specific fields
 192→	settings.Enabled = true
 193→	if opts.LocalDev {
 194→		settings.LocalDev = true
 195→	}
 196→	if opts.AbsoluteGitHookPath {
 197→		settings.AbsoluteGitHookPath = true
 198→	}
 199→
 200→	// Set push_sessions option if --skip-push-sessions flag was provided
 201→	if opts.SkipPushSessions {
 202→		if settings.StrategyOptions == nil {
 203→			settings.StrategyOptions = make(map[string]interface{})
 204→		}
 205→		settings.StrategyOptions["push_sessions"] = false
 206→	}
 207→
 208→	// Determine which settings file to write to
 209→	// First run always creates settings.json (no prompt)
 210→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
 211→	if err != nil {
 212→		entireDirAbs = paths.EntireDir // Fallback to relative
 213→	}
 214→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, opts.UseLocalSettings, opts.UseProjectSettings)
 215→
 216→	if showNotification {
 217→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
 218→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
 219→	}
 220→
 221→	// Save settings to the appropriate file.
 222→	saveSettings := func() error {
 223→		if shouldUseLocal {
 224→			return SaveEntireSettingsLocal(ctx, settings)
 225→		}
 226→		return SaveEntireSettings(ctx, settings)
 227→	}
 228→	if err := saveSettings(); err != nil {
 229→		return fmt.Errorf("failed to save settings: %w", err)
 230→	}
 231→
 232→	// Use settings values (merged from existing config + flags) for hook installation
 233→	// This ensures re-running `entire enable` without flags preserves existing settings
 234→	if _, err := strategy.InstallGitHook(ctx, true, settings.LocalDev, settings.AbsoluteGitHookPath); err != nil {
 235→		return fmt.Errorf("failed to install git hooks: %w", err)
 236→	}
 237→	strategy.CheckAndWarnHookManagers(ctx, w, settings.LocalDev, settings.AbsoluteGitHookPath)
 238→	fmt.Fprintln(w, "✓ Hooks installed")
 239→
 240→	configDisplay := configDisplayProject
 241→	if shouldUseLocal {
 242→		configDisplay = configDisplayLocal
 243→	}
 244→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplay)
 245→
 246→	// Ask about telemetry consent (only if not already asked)
 247→	fmt.Fprintln(w)
 248→	if err := promptTelemetryConsent(settings, opts.Telemetry); err != nil {
 249→		return fmt.Errorf("telemetry consent: %w", err)
 250→	}
 251→	// Save again to persist telemetry choice
 252→	if err := saveSettings(); err != nil {
 253→		return fmt.Errorf("failed to save settings: %w", err)
 254→	}
 255→
 256→	if err := strategy.EnsureSetup(ctx); err != nil {
 257→		return fmt.Errorf("failed to setup strategy: %w", err)
 258→	}
 259→
 260→	fmt.Fprintln(w, "\nReady.")
 261→
 262→	return nil
 263→}
