 265→// runEnable is a simple enable that just sets the enabled flag (for programmatic use).
 266→func runEnable(ctx context.Context, w io.Writer) error {
 267→	settings, err := LoadEntireSettings(ctx)
 268→	if err != nil {
 269→		return fmt.Errorf("failed to load settings: %w", err)
 270→	}
 271→
 272→	settings.Enabled = true
 273→	if err := SaveEntireSettings(ctx, settings); err != nil {
 274→		return fmt.Errorf("failed to save settings: %w", err)
 275→	}
 276→
 277→	fmt.Fprintln(w, "Entire is now enabled.")
 278→	return nil
 279→}
