 281→func runDisable(ctx context.Context, w io.Writer, useProjectSettings bool) error {
 282→	settings, err := LoadEntireSettings(ctx)
 283→	if err != nil {
 284→		return fmt.Errorf("failed to load settings: %w", err)
 285→	}
 286→
 287→	settings.Enabled = false
 288→
 289→	// If --project flag is specified, always write to project settings
 290→	if useProjectSettings {
 291→		if err := SaveEntireSettings(ctx, settings); err != nil {
 292→			return fmt.Errorf("failed to save settings: %w", err)
 293→		}
 294→	} else {
 295→		// Always write to local settings file (create if doesn't exist)
 296→		if err := SaveEntireSettingsLocal(ctx, settings); err != nil {
 297→			return fmt.Errorf("failed to save local settings: %w", err)
 298→		}
 299→	}
 300→
 301→	fmt.Fprintln(w, "Entire is now disabled.")
 302→	return nil
 303→}
