 309→// Returns true if the caller should exit (i.e., Entire is disabled).
 310→// On error reading settings, defaults to enabled (returns false).
 311→func checkDisabledGuard(ctx context.Context, w io.Writer) bool {
 312→	enabled, err := IsEnabled(ctx)
