 324→// uninstallDeselectedAgentHooks removes hooks for agents that were previously
 325→// installed but are not in the selected list. This handles the case where a user
 326→// re-runs `entire enable` and deselects an agent.
 327→func uninstallDeselectedAgentHooks(ctx context.Context, w io.Writer, selectedAgents []agent.Agent) error {
 328→	installedNames := GetAgentsWithHooksInstalled(ctx)
 329→	if len(installedNames) == 0 {
 330→		return nil
 331→	}
 332→
 333→	selectedSet := make(map[types.AgentName]struct{}, len(selectedAgents))
 334→	for _, ag := range selectedAgents {
 335→		selectedSet[ag.Name()] = struct{}{}
 336→	}
 337→
 338→	var errs []error
 339→	for _, name := range installedNames {
 340→		if _, selected := selectedSet[name]; selected {
 341→			continue
 342→		}
 343→		ag, err := agent.Get(name)
 344→		if err != nil {
 345→			continue
 346→		}
 347→		hookAgent, ok := ag.(agent.HookSupport)
 348→		if !ok {
 349→			continue
 350→		}
 351→		if err := hookAgent.UninstallHooks(ctx); err != nil {
 352→			errs = append(errs, fmt.Errorf("failed to uninstall %s hooks: %w", ag.Type(), err))
 353→		} else {
 354→			fmt.Fprintf(w, "Removed %s hooks\n", ag.Type())
 355→		}
 356→	}
 357→	return errors.Join(errs...)
 358→}
