 376→// detectOrSelectAgent tries to auto-detect agents, or prompts the user to select.
 377→// Returns the detected/selected agents and any error.
 378→//
 379→// On first run (no hooks installed):
 380→//   - Single detected agent: used automatically
 381→//   - Multiple/no detected agents: interactive multi-select prompt
 382→//
 383→// On re-run (hooks already installed):
 384→//   - Always shows the interactive multi-select
 385→//   - Pre-selects only agents that have hooks installed (respects prior deselection)
 386→//
 387→// selectFn overrides the interactive prompt for testing. When nil, the real form is used.
 388→// It receives available agent names and returns the selected names.
 389→func detectOrSelectAgent(ctx context.Context, w io.Writer, selectFn func(available []string) ([]string, error)) ([]agent.Agent, error) {
 390→	// Check for agents with hooks already installed (re-run detection)
 391→	installedAgentNames := GetAgentsWithHooksInstalled(ctx)
 392→	hasInstalledHooks := len(installedAgentNames) > 0
 393→
 394→	// Try auto-detection
 395→	detected := agent.DetectAll(ctx)
 396→
 397→	// First run: use existing auto-detect shortcuts
 398→	if !hasInstalledHooks {
 399→		switch {
 400→		case len(detected) == 1:
 401→			fmt.Fprintf(w, "Detected agent: %s\n\n", detected[0].Type())
 402→			return detected, nil
 403→
 404→		case len(detected) > 1:
 405→			agentTypes := make([]string, 0, len(detected))
 406→			for _, ag := range detected {
 407→				agentTypes = append(agentTypes, string(ag.Type()))
 408→			}
 409→			fmt.Fprintf(w, "Detected multiple agents: %s\n", strings.Join(agentTypes, ", "))
 410→			fmt.Fprintln(w)
 411→		}
 412→	}
 413→
 414→	// Check if we can prompt interactively
 415→	if !canPromptInteractively() {
 416→		if hasInstalledHooks {
 417→			// Re-run without TTY — keep currently installed agents
 418→			agents := make([]agent.Agent, 0, len(installedAgentNames))
 419→			for _, name := range installedAgentNames {
 420→				ag, err := agent.Get(name)
 421→				if err != nil {
 422→					continue
 423→				}
 424→				agents = append(agents, ag)
 425→			}
 426→			return agents, nil
 427→		}
 428→		if len(detected) > 0 {
 429→			return detected, nil
 430→		}
 431→		defaultAgent := agent.Default()
 432→		if defaultAgent == nil {
 433→			return nil, errors.New("no default agent available")
 434→		}
 435→		fmt.Fprintf(w, "Agent: %s (use --agent to change)\n\n", defaultAgent.Type())
 436→		return []agent.Agent{defaultAgent}, nil
 437→	}
 438→
 439→	if !hasInstalledHooks && len(detected) == 0 {
 440→		fmt.Fprintln(w, "No agent configuration detected (e.g., "+strings.Join(agent.StringList(), ", ")+").")
 441→		fmt.Fprintln(w, "This is normal - some agents don't require a config directory.")
 442→		fmt.Fprintln(w)
 443→	}
 444→
 445→	// Build pre-selection set.
 446→	// On re-run: only pre-select agents with hooks installed (respect prior deselection).
 447→	// On first run: pre-select all detected agents.
 448→	preSelectedSet := make(map[types.AgentName]struct{})
 449→	if hasInstalledHooks {
 450→		for _, name := range installedAgentNames {
 451→			preSelectedSet[name] = struct{}{}
 452→		}
 453→	} else {
 454→		for _, ag := range detected {
 455→			preSelectedSet[ag.Name()] = struct{}{}
 456→		}
 457→	}
 458→
 459→	// Build options from registered agents
 460→	agentNames := agent.List()
 461→	options := make([]huh.Option[string], 0, len(agentNames))
 462→	for _, name := range agentNames {
 463→		ag, err := agent.Get(name)
 464→		if err != nil {
 465→			continue
 466→		}
 467→		// Only show agents that support hooks
 468→		if _, ok := ag.(agent.HookSupport); !ok {
 469→			continue
 470→		}
 471→		opt := huh.NewOption(string(ag.Type()), string(name))
 472→		if _, isPreSelected := preSelectedSet[name]; isPreSelected {
 473→			opt = opt.Selected(true)
 474→		}
 475→		options = append(options, opt)
 476→	}
 477→
 478→	if len(options) == 0 {
 479→		return nil, errors.New("no agents with hook support available")
 480→	}
 481→
 482→	// Collect available agent names for the selector
 483→	availableNames := make([]string, 0, len(options))
 484→	for _, opt := range options {
 485→		availableNames = append(availableNames, opt.Value)
 486→	}
 487→
 488→	var selectedAgentNames []string
 489→	if selectFn != nil {
 490→		var err error
 491→		selectedAgentNames, err = selectFn(availableNames)
 492→		if err != nil {
 493→			return nil, err
 494→		}
 495→		if len(selectedAgentNames) == 0 {
 496→			return nil, errors.New("no agents selected")
 497→		}
 498→	} else {
 499→		form := NewAccessibleForm(
 500→			huh.NewGroup(
 501→				huh.NewMultiSelect[string]().
 502→					Title("Which agents are you using?").
 503→					Description("Use space to select, enter to confirm.").
 504→					Options(options...).
 505→					Validate(func(selected []string) error {
 506→						if len(selected) == 0 {
 507→							return errors.New("please select at least one agent")
 508→						}
 509→						return nil
 510→					}).
 511→					Value(&selectedAgentNames),
 512→			),
 513→		)
 514→		if err := form.Run(); err != nil {
 515→			return nil, fmt.Errorf("agent selection cancelled: %w", err)
 516→		}
 517→	}
 518→
 519→	selectedAgents := make([]agent.Agent, 0, len(selectedAgentNames))
 520→	for _, name := range selectedAgentNames {
 521→		selectedAgent, err := agent.Get(types.AgentName(name))
 522→		if err != nil {
 523→			return nil, fmt.Errorf("failed to get selected agent %s: %w", name, err)
 524→		}
 525→		selectedAgents = append(selectedAgents, selectedAgent)
 526→	}
 527→
 528→	agentTypes := make([]string, 0, len(selectedAgents))
 529→	for _, ag := range selectedAgents {
 530→		agentTypes = append(agentTypes, string(ag.Type()))
 531→	}
 532→	fmt.Fprintf(w, "\nSelected agents: %s\n\n", strings.Join(agentTypes, ", "))
 533→	return selectedAgents, nil
 534→}
