 579→// setupAgentHooksNonInteractive sets up hooks for a specific agent non-interactively.
 580→// If strategyName is provided, it sets the strategy; otherwise uses default.
 581→func setupAgentHooksNonInteractive(ctx context.Context, w io.Writer, ag agent.Agent, opts EnableOptions) error {
 582→	agentName := ag.Name()
 583→	// Check if agent supports hooks
 584→	hookAgent, ok := ag.(agent.HookSupport)
 585→	if !ok {
 586→		return fmt.Errorf("agent %s does not support hooks", agentName)
 587→	}
 588→
 589→	fmt.Fprintf(w, "Agent: %s\n\n", ag.Type())
 590→
 591→	// Install agent hooks (agent hooks don't depend on settings)
 592→	installedHooks, err := hookAgent.InstallHooks(ctx, opts.LocalDev, opts.ForceHooks)
 593→	if err != nil {
 594→		return fmt.Errorf("failed to install hooks for %s: %w", agentName, err)
 595→	}
 596→
 597→	// Setup .entire directory
 598→	if _, err := setupEntireDirectory(ctx); err != nil {
 599→		return fmt.Errorf("failed to setup .entire directory: %w", err)
 600→	}
 601→
 602→	// Load existing settings to preserve other options (like strategy_options.push)
 603→	settings, err := LoadEntireSettings(ctx)
 604→	if err != nil {
 605→		// If we can't load, start with defaults
 606→		settings = &EntireSettings{}
 607→	}
 608→	settings.Enabled = true
 609→	if opts.LocalDev {
 610→		settings.LocalDev = true
 611→	}
 612→	if opts.AbsoluteGitHookPath {
 613→		settings.AbsoluteGitHookPath = true
 614→	}
 615→
 616→	// Set push_sessions option if --skip-push-sessions flag was provided
 617→	if opts.SkipPushSessions {
 618→		if settings.StrategyOptions == nil {
 619→			settings.StrategyOptions = make(map[string]interface{})
 620→		}
 621→		settings.StrategyOptions["push_sessions"] = false
 622→	}
 623→
 624→	// Handle telemetry for non-interactive mode
 625→	// Note: if telemetry is nil (not configured), it defaults to disabled
 626→	if !opts.Telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
 627→		f := false
 628→		settings.Telemetry = &f
 629→	}
 630→
 631→	if err := SaveEntireSettings(ctx, settings); err != nil {
 632→		return fmt.Errorf("failed to save settings: %w", err)
 633→	}
 634→
 635→	// Use settings values (merged from existing config + flags) for hook installation
 636→	// This ensures re-running `entire enable --agent X` without flags preserves existing settings
 637→	if _, err := strategy.InstallGitHook(ctx, true, settings.LocalDev, settings.AbsoluteGitHookPath); err != nil {
 638→		return fmt.Errorf("failed to install git hooks: %w", err)
 639→	}
 640→	strategy.CheckAndWarnHookManagers(ctx, w, settings.LocalDev, settings.AbsoluteGitHookPath)
 641→
 642→	if installedHooks == 0 {
 643→		msg := fmt.Sprintf("Hooks for %s already installed", ag.Description())
 644→		if ag.IsPreview() {
 645→			msg += " (Preview)"
 646→		}
 647→		fmt.Fprintf(w, "%s\n", msg)
 648→	} else {
 649→		msg := fmt.Sprintf("Installed %d hooks for %s", installedHooks, ag.Description())
 650→		if ag.IsPreview() {
 651→			msg += " (Preview)"
 652→		}
 653→		fmt.Fprintf(w, "%s\n", msg)
 654→	}
 655→
 656→	fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplayProject)
 657→
 658→	if err := strategy.EnsureSetup(ctx); err != nil {
 659→		return fmt.Errorf("failed to setup strategy: %w", err)
 660→	}
 661→
 662→	fmt.Fprintln(w, "\nReady.")
 663→
 664→	return nil
 665→}
