 677→// - The --local and --project flags
 678→// Returns (useLocal, showNotification).
 679→func determineSettingsTarget(entireDir string, useLocal, useProject bool) (bool, bool) {
 680→	// Explicit --local flag always uses local settings
 681→	if useLocal {
 682→		return true, false
 683→	}
 684→
 685→	// Explicit --project flag always uses project settings
 686→	if useProject {
 687→		return false, false
 688→	}
