 701→// setupEntireDirectory creates the .entire directory and gitignore.
 702→// Returns true if the directory was created, false if it already existed.
 703→func setupEntireDirectory(ctx context.Context) (bool, error) { //nolint:unparam // already present in codebase
 704→	// Get absolute path for the .entire directory
 705→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
 706→	if err != nil {
 707→		entireDirAbs = paths.EntireDir // Fallback to relative
 708→	}
