 771→// shellCompletionComment is the comment preceding the completion line
 772→const shellCompletionComment = "# Entire CLI shell completion"
 773→
 774→// errUnsupportedShell is returned when the user's shell is not supported for completion.
 775→var errUnsupportedShell = errors.New("unsupported shell")
 776→
 777→// shellCompletionTarget returns the rc file path and completion lines for the
 778→// user's current shell.
 779→func shellCompletionTarget() (shellName, rcFile, completionLine string, err error) {
 780→	home, err := os.UserHomeDir()
 781→	if err != nil {
 782→		return "", "", "", fmt.Errorf("cannot determine home directory: %w", err)
 783→	}
 784→
 785→	shell := os.Getenv("SHELL")
 786→	switch {
 787→	case strings.Contains(shell, "zsh"):
 788→		return "Zsh",
 789→			filepath.Join(home, ".zshrc"),
 790→			"autoload -Uz compinit && compinit && source <(entire completion zsh)",
 791→			nil
 792→	case strings.Contains(shell, "bash"):
 793→		bashRC := filepath.Join(home, ".bashrc")
 794→		if _, err := os.Stat(filepath.Join(home, ".bash_profile")); err == nil {
 795→			bashRC = filepath.Join(home, ".bash_profile")
 796→		}
 797→		return "Bash",
 798→			bashRC,
 799→			"source <(entire completion bash)",
 800→			nil
 801→	case strings.Contains(shell, "fish"):
 802→		return "Fish",
 803→			filepath.Join(home, ".config", "fish", "config.fish"),
 804→			"entire completion fish | source",
 805→			nil
 806→	default:
 807→		return "", "", "", errUnsupportedShell
 808→	}
 809→}
 810→
 811→// promptShellCompletion offers to add shell completion to the user's rc file.
 812→// Only prompts if completion is not already configured.
 813→func promptShellCompletion(w io.Writer) error {
 814→	shellName, rcFile, completionLine, err := shellCompletionTarget()
 815→	if err != nil {
 816→		if errors.Is(err, errUnsupportedShell) {
 817→			fmt.Fprintf(w, "Note: Shell completion not available for your shell. Supported: zsh, bash, fish.\n")
 818→			return nil
 819→		}
 820→		return fmt.Errorf("shell completion: %w", err)
 821→	}
 822→
 823→	if isCompletionConfigured(rcFile) {
 824→		fmt.Fprintf(w, "✓ Shell completion already configured in %s\n", rcFile)
 825→		return nil
 826→	}
 827→
 828→	var selected string
 829→	form := NewAccessibleForm(
 830→		huh.NewGroup(
 831→			huh.NewSelect[string]().
 832→				Title(fmt.Sprintf("Enable shell completion? (detected: %s)", shellName)).
 833→				Options(
 834→					huh.NewOption("Yes", "yes"),
 835→					huh.NewOption("No", "no"),
 836→				).
 837→				Value(&selected),
 838→		),
 839→	)
 840→
 841→	if err := form.Run(); err != nil {
 842→		//nolint:nilerr // User cancelled - not a fatal error, just skip
 843→		return nil
 844→	}
 845→
 846→	if selected != "yes" {
 847→		return nil
 848→	}
 849→
 850→	if err := appendShellCompletion(rcFile, completionLine); err != nil {
 851→		return fmt.Errorf("failed to update %s: %w", rcFile, err)
 852→	}
 853→
 854→	fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
 855→	fmt.Fprintln(w, "  Restart your shell to activate")
 856→
 857→	return nil
 858→}
 859→
 860→// isCompletionConfigured checks if shell completion is already in the rc file.
 861→func isCompletionConfigured(rcFile string) bool {
 862→	//nolint:gosec // G304: rcFile is constructed from home dir + known filename, not user input
 863→	content, err := os.ReadFile(rcFile)
 864→	if err != nil {
 865→		return false // File doesn't exist or can't read, treat as not configured
 866→	}
 867→	return strings.Contains(string(content), "entire completion")
 868→}
 869→
 870→// appendShellCompletion adds the completion line to the rc file.
 871→func appendShellCompletion(rcFile, completionLine string) error {
 872→	if err := os.MkdirAll(filepath.Dir(rcFile), 0o700); err != nil {
 873→		return fmt.Errorf("creating directory: %w", err)
 874→	}
 875→	//nolint:gosec // G302: Shell rc files need 0644 for user readability
 876→	f, err := os.OpenFile(rcFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
 877→	if err != nil {
 878→		return fmt.Errorf("opening file: %w", err)
 879→	}
 880→	defer f.Close()
 881→
 882→	_, err = f.WriteString("\n" + shellCompletionComment + "\n" + completionLine + "\n")
 883→	if err != nil {
 884→		return fmt.Errorf("writing completion: %w", err)
 885→	}
 886→	return nil
 887→}
