 889→// promptTelemetryConsent asks the user if they want to enable telemetry.
 890→// It modifies settings.Telemetry based on the user's choice or flags.
 891→// The caller is responsible for saving settings.
 892→func promptTelemetryConsent(settings *EntireSettings, telemetryFlag bool) error {
 893→	// Handle --telemetry=false flag first (always overrides existing setting)
 894→	if !telemetryFlag {
 895→		f := false
 896→		settings.Telemetry = &f
 897→		return nil
 898→	}
 899→
 900→	// Skip if already asked
 901→	if settings.Telemetry != nil {
 902→		return nil
 903→	}
 904→
 905→	// Skip if env var disables telemetry (record as disabled)
 906→	if os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
 907→		f := false
 908→		settings.Telemetry = &f
 909→		return nil
 910→	}
 911→
 912→	consent := true // Default to Yes
 913→	form := NewAccessibleForm(
 914→		huh.NewGroup(
 915→			huh.NewConfirm().
 916→				Title("Help improve Entire CLI?").
 917→				Description("Share anonymous usage data. No code or personal info collected.").
 918→				Affirmative("Yes").
 919→				Negative("No").
 920→				Value(&consent),
 921→		),
 922→	)
 923→
 924→	if err := form.Run(); err != nil {
 925→		return fmt.Errorf("telemetry prompt: %w", err)
 926→	}
 927→
 928→	settings.Telemetry = &consent
 929→	return nil
