 932→// runUninstall completely removes Entire from the repository.
 933→func runUninstall(ctx context.Context, w, errW io.Writer, force bool) error {
 934→	// Check if we're in a git repository
 935→	if _, err := paths.WorktreeRoot(ctx); err != nil {
 936→		fmt.Fprintln(errW, "Not a git repository. Nothing to uninstall.")
 937→		return NewSilentError(errors.New("not a git repository"))
 938→	}
 939→
 940→	// Gather counts for display
 941→	sessionStateCount := countSessionStates(ctx)
 942→	shadowBranchCount := countShadowBranches(ctx)
 943→	gitHooksInstalled := strategy.IsGitHookInstalled(ctx)
 944→	agentsWithInstalledHooks := GetAgentsWithHooksInstalled(ctx)
 945→	entireDirExists := checkEntireDirExists(ctx)
 946→
 947→	// Check if there's anything to uninstall
 948→	if !entireDirExists && !gitHooksInstalled && sessionStateCount == 0 &&
 949→		shadowBranchCount == 0 && len(agentsWithInstalledHooks) == 0 {
 950→		fmt.Fprintln(w, "Entire is not installed in this repository.")
 951→		return nil
 952→	}
 953→
 954→	// Show confirmation prompt unless --force
 955→	if !force {
 956→		fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
 957→		if entireDirExists {
 958→			fmt.Fprintln(w, "  - .entire/ directory")
 959→		}
 960→		if gitHooksInstalled {
 961→			fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
 962→		}
 963→		if sessionStateCount > 0 {
 964→			fmt.Fprintf(w, "  - Session state files (%d)\n", sessionStateCount)
 965→		}
 966→		if shadowBranchCount > 0 {
 967→			fmt.Fprintf(w, "  - Shadow branches (%d)\n", shadowBranchCount)
 968→		}
 969→		if len(agentsWithInstalledHooks) > 0 {
 970→			displayNames := make([]string, 0, len(agentsWithInstalledHooks))
 971→			for _, name := range agentsWithInstalledHooks {
 972→				if ag, err := agent.Get(name); err == nil {
 973→					displayNames = append(displayNames, string(ag.Type()))
 974→				}
 975→			}
 976→			fmt.Fprintf(w, "  - Agent hooks (%s)\n", strings.Join(displayNames, ", "))
 977→		}
 978→		fmt.Fprintln(w)
 979→
 980→		var confirmed bool
 981→		form := NewAccessibleForm(
 982→			huh.NewGroup(
 983→				huh.NewConfirm().
 984→					Title("Are you sure you want to uninstall Entire?").
 985→					Affirmative("Yes, uninstall").
 986→					Negative("Cancel").
 987→					Value(&confirmed),
 988→			),
 989→		)
 990→
 991→		if err := form.Run(); err != nil {
 992→			return fmt.Errorf("confirmation cancelled: %w", err)
 993→		}
 994→
 995→		if !confirmed {
 996→			fmt.Fprintln(w, "Uninstall cancelled.")
 997→			return nil
 998→		}
 999→	}
1000→
1001→	fmt.Fprintln(w, "\nUninstalling Entire CLI...")
1002→
1003→	// 1. Remove agent hooks (lowest risk)
1004→	if err := removeAgentHooks(ctx, w); err != nil {
1005→		fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %v\n", err)
1006→	}
1007→
1008→	// 2. Remove git hooks
1009→	removed, err := strategy.RemoveGitHook(ctx)
1010→	if err != nil {
1011→		fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
1012→	} else if removed > 0 {
1013→		fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
1014→	}
1015→
1016→	// 3. Remove session state files
1017→	statesRemoved, err := removeAllSessionStates(ctx)
1018→	if err != nil {
1019→		fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
1020→	} else if statesRemoved > 0 {
1021→		fmt.Fprintf(w, "  Removed session states (%d)\n", statesRemoved)
1022→	}
1023→
1024→	// 4. Remove .entire/ directory
1025→	if err := removeEntireDirectory(ctx); err != nil {
1026→		fmt.Fprintf(errW, "Warning: failed to remove .entire directory: %v\n", err)
1027→	} else if entireDirExists {
1028→		fmt.Fprintln(w, "  Removed .entire directory")
1029→	}
1030→
1031→	// 5. Remove shadow branches
1032→	branchesRemoved, err := removeAllShadowBranches(ctx)
1033→	if err != nil {
1034→		fmt.Fprintf(errW, "Warning: failed to remove shadow branches: %v\n", err)
1035→	} else if branchesRemoved > 0 {
1036→		fmt.Fprintf(w, "  Removed %d shadow branches\n", branchesRemoved)
1037→	}
1038→
1039→	fmt.Fprintln(w, "\nEntire CLI uninstalled successfully.")
1040→	return nil
1041→}
1042→
1043→// countSessionStates returns the number of active session state files.
1044→func countSessionStates(ctx context.Context) int {
1045→	store, err := session.NewStateStore(ctx)
1046→	if err != nil {
1047→		return 0
1048→	}
1049→	states, err := store.List(ctx)
1050→	if err != nil {
1051→		return 0
1052→	}
1053→	return len(states)
1054→}
1055→
1056→// countShadowBranches returns the number of shadow branches.
1057→func countShadowBranches(ctx context.Context) int {
1058→	branches, err := strategy.ListShadowBranches(ctx)
1059→	if err != nil {
1060→		return 0
1061→	}
1062→	return len(branches)
1063→}
1064→
1065→// checkEntireDirExists checks if the .entire directory exists.
1066→func checkEntireDirExists(ctx context.Context) bool {
1067→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
1068→	if err != nil {
1069→		entireDirAbs = paths.EntireDir
1070→	}
1071→	_, err = os.Stat(entireDirAbs)
1072→	return err == nil
1073→}
1074→
1075→// removeAgentHooks removes hooks from all agents that support hooks.
1076→func removeAgentHooks(ctx context.Context, w io.Writer) error {
1077→	var errs []error
1078→	for _, name := range agent.List() {
1079→		ag, err := agent.Get(name)
1080→		if err != nil {
1081→			continue
1082→		}
1083→		hs, ok := ag.(agent.HookSupport)
1084→		if !ok {
1085→			continue
1086→		}
1087→		wasInstalled := hs.AreHooksInstalled(ctx)
1088→		if err := hs.UninstallHooks(ctx); err != nil {
1089→			errs = append(errs, err)
1090→		} else if wasInstalled {
1091→			fmt.Fprintf(w, "  Removed %s hooks\n", ag.Type())
1092→		}
1093→	}
1094→	return errors.Join(errs...)
1095→}
1096→
1097→// removeAllSessionStates removes all session state files and the directory.
1098→func removeAllSessionStates(ctx context.Context) (int, error) {
1099→	store, err := session.NewStateStore(ctx)
1100→	if err != nil {
1101→		return 0, fmt.Errorf("failed to create state store: %w", err)
1102→	}
1103→
1104→	// Count states before removing
1105→	states, err := store.List(ctx)
1106→	if err != nil {
1107→		return 0, fmt.Errorf("failed to list session states: %w", err)
1108→	}
1109→	count := len(states)
1110→
1111→	// Remove the entire directory
1112→	if err := store.RemoveAll(); err != nil {
1113→		return 0, fmt.Errorf("failed to remove session states: %w", err)
1114→	}
1115→
1116→	return count, nil
1117→}
1118→
1119→// removeEntireDirectory removes the .entire directory.
1120→func removeEntireDirectory(ctx context.Context) error {
1121→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
1122→	if err != nil {
1123→		entireDirAbs = paths.EntireDir
1124→	}
1125→	if err := os.RemoveAll(entireDirAbs); err != nil {
1126→		return fmt.Errorf("failed to remove .entire directory: %w", err)
1127→	}
1128→	return nil
1129→}
1130→
1131→// removeAllShadowBranches removes all shadow branches.
1132→func removeAllShadowBranches(ctx context.Context) (int, error) {
1133→	branches, err := strategy.ListShadowBranches(ctx)
1134→	if err != nil {
1135→		return 0, fmt.Errorf("failed to list shadow branches: %w", err)
1136→	}
1137→	if len(branches) == 0 {
1138→		return 0, nil
1139→	}
1140→	deleted, _, err := strategy.DeleteShadowBranches(ctx, branches)
1141→	return len(deleted), err
1142→}
