 23→// PrePromptState stores the state captured before a user prompt
 24→type PrePromptState struct {
 25→	SessionID      string   `json:"session_id"`
 26→	Timestamp      string   `json:"timestamp"`
 27→	UntrackedFiles []string `json:"untracked_files"`
 28→
 29→	// TranscriptOffset is the unified transcript position when this state was captured.
 30→	// For Claude Code (JSONL), this is the line count.
 31→	// For Gemini CLI (JSON), this is the message count.
 32→	// Zero means not set or session just started.
 33→	TranscriptOffset int `json:"transcript_offset,omitempty"`
 34→
 35→	// LastTranscriptIdentifier is the agent-specific identifier at the transcript position.
 36→	// UUID for Claude Code, message ID for Gemini CLI. Optional metadata.
 37→	LastTranscriptIdentifier string `json:"last_transcript_identifier,omitempty"`
 38→
 39→	// Deprecated: StartMessageIndex is the old Gemini-specific field.
 40→	// Migrated to TranscriptOffset on load.
 41→	StartMessageIndex int `json:"start_message_index,omitempty"`
 42→
 43→	// Deprecated: StepTranscriptStart is the old Claude-specific field.
 44→	// Migrated to TranscriptOffset on load.
 45→	StepTranscriptStart int `json:"step_transcript_start,omitempty"`
 46→
 47→	// Deprecated: LastTranscriptLineCount is the oldest name for transcript position.
 48→	// Migrated to TranscriptOffset on load.
 49→	LastTranscriptLineCount int `json:"last_transcript_line_count,omitempty"`
 50→}
 51→
 52→// PreUntrackedFiles returns the untracked files list, or nil if the receiver is nil.
 53→// This nil-vs-empty distinction lets DetectFileChanges know whether to skip new-file detection.
 54→// When the receiver is non-nil but UntrackedFiles is nil (e.g., old state files deserialized with
 55→// "untracked_files": null), returns an empty non-nil slice so that all current untracked files
 56→// are correctly treated as new.
 57→func (s *PrePromptState) PreUntrackedFiles() []string {
 58→	if s == nil {
 59→		return nil
 60→	}
 61→	if s.UntrackedFiles == nil {
 62→		return []string{}
 63→	}
 64→	return s.UntrackedFiles
 65→}
 66→
 67→// normalizePrePromptState migrates deprecated fields after loading from JSON.
 68→func (s *PrePromptState) normalizePrePromptState() {
 69→	// Migrate the oldest field to the intermediate field first
 70→	if s.StepTranscriptStart == 0 && s.LastTranscriptLineCount > 0 {
 71→		s.StepTranscriptStart = s.LastTranscriptLineCount
 72→	}
 73→	s.LastTranscriptLineCount = 0
 74→
 75→	// Migrate all deprecated fields to the unified TranscriptOffset
 76→	if s.TranscriptOffset == 0 {
 77→		if s.StepTranscriptStart > 0 {
 78→			s.TranscriptOffset = s.StepTranscriptStart
 79→		} else if s.StartMessageIndex > 0 {
 80→			s.TranscriptOffset = s.StartMessageIndex
 81→		}
 82→	}
 83→	s.StepTranscriptStart = 0
 84→	s.StartMessageIndex = 0
 85→}
 86→
 87→// CapturePrePromptState captures current untracked files and transcript position before a prompt
 88→// and saves them to a state file.
 89→//
 90→// The agent parameter is used to determine the transcript position via TranscriptAnalyzer.
 91→// If the agent does not implement TranscriptAnalyzer, the transcript offset will be 0.
 92→// The sessionRef parameter is optional — if empty, transcript position won't be captured.
 93→//
 94→// Works correctly from any subdirectory within the repository.
 95→func CapturePrePromptState(ctx context.Context, ag agent.Agent, sessionID, sessionRef string) error {
 96→	if sessionID == "" {
 97→		sessionID = unknownSessionID
 98→	}
 99→
100→	// Get absolute path for tmp directory
101→	tmpDirAbs, err := paths.AbsPath(ctx, paths.EntireTmpDir)
102→	if err != nil {
103→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
104→	}
105→
106→	// Create tmp directory if it doesn't exist
107→	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
108→		return fmt.Errorf("failed to create tmp directory: %w", err)
109→	}
110→
111→	// Get list of untracked files (excluding .entire directory itself)
112→	untrackedFiles, err := getUntrackedFilesForState(ctx)
113→	if err != nil {
114→		return fmt.Errorf("failed to get untracked files: %w", err)
115→	}
116→
117→	// Get transcript position using TranscriptAnalyzer if available
118→	var transcriptOffset int
119→	if analyzer, ok := ag.(agent.TranscriptAnalyzer); ok && sessionRef != "" {
120→		pos, posErr := analyzer.GetTranscriptPosition(sessionRef)
121→		if posErr != nil {
122→			logging.Warn(logging.WithComponent(ctx, "state"), "failed to get transcript position",
123→				slog.String("error", posErr.Error()))
124→		} else {
125→			transcriptOffset = pos
126→		}
127→	}
128→
129→	// Create state file
130→	stateFile := prePromptStateFile(ctx, sessionID)
131→	state := PrePromptState{
132→		SessionID:        sessionID,
133→		Timestamp:        time.Now().UTC().Format(time.RFC3339),
134→		UntrackedFiles:   untrackedFiles,
135→		TranscriptOffset: transcriptOffset,
136→	}
137→
138→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
139→	if err != nil {
140→		return fmt.Errorf("failed to marshal state: %w", err)
141→	}
142→
143→	if err := os.WriteFile(stateFile, data, 0o600); err != nil {
144→		return fmt.Errorf("failed to write state file: %w", err)
145→	}
146→
147→	logging.Debug(logging.WithComponent(ctx, "state"), "captured state before prompt",
148→		slog.Int("untracked_files", len(untrackedFiles)),
149→		slog.Int("transcript_offset", transcriptOffset))
150→	return nil
151→}
152→
153→// LoadPrePromptState loads previously captured state.
154→// Returns nil if no state file exists.
155→func LoadPrePromptState(ctx context.Context, sessionID string) (*PrePromptState, error) {
156→	stateFile := prePromptStateFile(ctx, sessionID)
157→
158→	if !fileExists(stateFile) {
159→		return nil, nil //nolint:nilnil // already present in codebase
160→	}
161→
162→	data, err := os.ReadFile(stateFile) //nolint:gosec // Reading from controlled git metadata path
163→	if err != nil {
164→		return nil, fmt.Errorf("failed to read state file: %w", err)
165→	}
166→
167→	var state PrePromptState
168→	if err := json.Unmarshal(data, &state); err != nil {
169→		return nil, fmt.Errorf("failed to unmarshal state: %w", err)
170→	}
171→
172→	state.normalizePrePromptState()
173→
174→	return &state, nil
175→}
