253→// filterToUncommittedFiles removes files from the list that are already committed to HEAD
254→// with matching content. This prevents re-adding files that an agent committed mid-turn
255→// (already condensed by PostCommit) back to FilesTouched via SaveStep. Files not in
256→// HEAD or with different content in the working tree are kept. Fails open: if any git
257→// operation errors, returns the original list unchanged.
258→func filterToUncommittedFiles(ctx context.Context, files []string, repoRoot string) []string {
259→	if len(files) == 0 {
260→		return files
261→	}
262→
263→	repo, err := openRepository(ctx)
264→	if err != nil {
265→		return files // fail open
266→	}
267→
268→	head, err := repo.Head()
269→	if err != nil {
270→		return files // fail open (empty repo, detached HEAD, etc.)
271→	}
272→
273→	commit, err := repo.CommitObject(head.Hash())
274→	if err != nil {
275→		return files // fail open
276→	}
277→
278→	headTree, err := commit.Tree()
279→	if err != nil {
280→		return files // fail open
281→	}
282→
283→	var result []string
284→	for _, relPath := range files {
285→		headFile, err := headTree.File(relPath)
286→		if err != nil {
287→			// File not in HEAD — it's uncommitted
288→			result = append(result, relPath)
289→			continue
290→		}
291→
292→		// File is in HEAD — compare content with working tree
293→		absPath := filepath.Join(repoRoot, relPath)
294→		workingContent, err := os.ReadFile(absPath) //nolint:gosec // path from controlled source
295→		if err != nil {
296→			// Can't read working tree file (deleted?) — keep it
297→			result = append(result, relPath)
298→			continue
299→		}
300→
301→		headContent, err := headFile.Contents()
302→		if err != nil {
303→			result = append(result, relPath)
304→			continue
305→		}
306→
307→		if string(workingContent) != headContent {
308→			// Working tree differs from HEAD — uncommitted changes
309→			result = append(result, relPath)
310→		}
311→		// else: content matches HEAD — already committed, skip
312→	}
313→
314→	return result
315→}
