503→// FindActivePreTaskFile finds an active pre-task file in .entire/tmp/ and returns
504→// the parent Task's tool_use_id. Returns ("", false) if no pre-task file exists.
505→// When multiple pre-task files exist (nested subagents), returns the most recently
506→// modified one.
507→// Works correctly from any subdirectory within the repository.
508→func FindActivePreTaskFile(ctx context.Context) (taskToolUseID string, found bool) {
509→	tmpDirAbs, err := paths.AbsPath(ctx, paths.EntireTmpDir)
510→	if err != nil {
511→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
512→	}
513→	entries, err := os.ReadDir(tmpDirAbs)
514→	if err != nil {
515→		return "", false
516→	}
517→
518→	var latestFile string
519→	var latestTime time.Time
520→
521→	for _, entry := range entries {
522→		if entry.IsDir() {
523→			continue
524→		}
525→		name := entry.Name()
526→		if !strings.HasPrefix(name, preTaskFilePrefix) || !strings.HasSuffix(name, ".json") {
527→			continue
528→		}
529→
530→		// Check modification time for nested subagent handling
531→		info, err := entry.Info()
532→		if err != nil {
533→			continue
534→		}
535→		if latestFile == "" || info.ModTime().After(latestTime) {
536→			latestFile = name
537→			latestTime = info.ModTime()
538→		}
539→	}
540→
541→	if latestFile == "" {
542→		return "", false
543→	}
544→
545→	// Extract tool_use_id from filename: pre-task-<tool_use_id>.json
546→	toolUseID := strings.TrimPrefix(latestFile, preTaskFilePrefix)
547→	toolUseID = strings.TrimSuffix(toolUseID, ".json")
548→	return toolUseID, true
549→}
