552→// It counts existing checkpoint files in the task metadata checkpoints directory.
553→// Returns 1 if no checkpoints exist yet.
554→func GetNextCheckpointSequence(sessionID, taskToolUseID string) int {
555→	// Use the session ID directly as the metadata directory name
556→	sessionMetadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
557→	taskMetadataDir := strategy.TaskMetadataDir(sessionMetadataDir, taskToolUseID)
558→	checkpointsDir := filepath.Join(taskMetadataDir, "checkpoints")
559→
560→	entries, err := os.ReadDir(checkpointsDir)
561→	if err != nil {
562→		// Directory doesn't exist or can't be read - start at 1
563→		return 1
564→	}
565→
566→	// Count JSON files (checkpoints)
567→	count := 0
568→	for _, entry := range entries {
569→		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
570→			count++
571→		}
572→	}
573→
574→	return count + 1
575→}
