  3→// CapabilityDeclarer is implemented by agents that declare their capabilities
  4→// at registration time (e.g., external plugin agents). The As* helper functions
  5→// below use this interface to gate capability access: an agent must both implement
  6→// the optional interface AND declare the capability as true.
  7→//
  8→// Built-in agents (Claude Code, Gemini CLI, etc.) do NOT implement this interface.
  9→// For those agents, the As* helpers fall through to a direct type assertion,
 10→// preserving existing behavior.
 11→type CapabilityDeclarer interface {
 12→	DeclaredCapabilities() DeclaredCaps
 13→}
 14→
 15→// DeclaredCaps enumerates the optional interfaces an agent claims to support.
 16→type DeclaredCaps struct {
 17→	Hooks                  bool
 18→	TranscriptAnalyzer     bool
 19→	TranscriptPreparer     bool
 20→	TokenCalculator        bool
 21→	TextGenerator          bool
 22→	HookResponseWriter     bool
 23→	SubagentAwareExtractor bool
 24→}
 25→
 26→// AsHookSupport returns the agent as HookSupport if it both implements the
 27→// interface and (for CapabilityDeclarer agents) has declared the capability.
 28→func AsHookSupport(ag Agent) (HookSupport, bool) {
 29→	hs, ok := ag.(HookSupport)
 30→	if !ok {
 31→		return nil, false
 32→	}
 33→	if cd, ok := ag.(CapabilityDeclarer); ok {
 34→		return hs, cd.DeclaredCapabilities().Hooks
 35→	}
 36→	return hs, true
 37→}
 38→
 39→// AsTranscriptAnalyzer returns the agent as TranscriptAnalyzer if it both
 40→// implements the interface and (for CapabilityDeclarer agents) has declared the capability.
