 42→	ta, ok := ag.(TranscriptAnalyzer)
 43→	if !ok {
 44→		return nil, false
 45→	}
 46→	if cd, ok := ag.(CapabilityDeclarer); ok {
 47→		return ta, cd.DeclaredCapabilities().TranscriptAnalyzer
 48→	}
 49→	return ta, true
 50→}
 51→
 52→// AsTranscriptPreparer returns the agent as TranscriptPreparer if it both
 53→// implements the interface and (for CapabilityDeclarer agents) has declared the capability.
 54→func AsTranscriptPreparer(ag Agent) (TranscriptPreparer, bool) {
 55→	tp, ok := ag.(TranscriptPreparer)
